last=0
def control(obs):
 global last
 h=obs['hitch_deg']; th=math.radians(-h)
 cam=obs.get('views',{}).get('camera')
 if not cam: return (1.7*h,-0.45,-23)
 sides=[[],[]]
 for b,d in cam.get('walls',[]):
  a=math.radians(b); dx=d*math.cos(a); dy=d*math.sin(a)
  s=-dx*math.cos(th)-dy*math.sin(th)
  y=-dx*math.sin(th)+dy*math.cos(th)
  if s>0.3: sides[0 if y<0 else 1].append((s,y))
 def at(points,x):
  points=sorted(points)
  if not points:return None
  for i in range(len(points)-1):
   a,b=points[i],points[i+1]
   if a[0]<=x<=b[0]:return a[1]+(b[1]-a[1])*(x-a[0])/max(.001,b[0]-a[0])
  return min(points,key=lambda p:abs(p[0]-x))[1]
 L=3.6
 ys=[at(p,L) for p in sides]
 y=sum(ys)/2 if all(v is not None for v in ys) else 0
 hd=math.degrees(math.atan(2*2.6*y/(L*L)))
 hd=max(-29,min(29,hd))
 eq=math.degrees(math.atan(2.75*math.sin(math.radians(h))/(2.6+1.05*math.cos(math.radians(h)))))
 steer=max(-34,min(34,eq+1.8*(h-hd)))
 if cam.get('target_corners') and obs['t']-last>8:
  last=obs['t']; print('bay',cam['target_corners']); wake('Bay markings visible')
 return (steer,-0.65,-23)

